alter table dm_private.bank_questions drop constraint bank_runtime_valid;
alter table dm_private.bank_questions add constraint bank_runtime_valid check(runtime_payload is null or(jsonb_typeof(runtime_payload)='object'and runtime_payload->>'kind'in('mcq','msq','nat','drawing')));

create or replace function public.upsert_question_bank_runtime_batch(p_records jsonb)
returns integer language plpgsql security definer set search_path=pg_catalog,dm_private as $$
declare r jsonb;v jsonb;q dm_private.bank_questions;a jsonb;m jsonb;correct numeric;wrong numeric;n integer:=0;drawing boolean;
begin
 if auth.role()is distinct from'service_role'then raise exception'Forbidden';end if;
 if jsonb_typeof(p_records)is distinct from'array'or jsonb_array_length(p_records)not between 1 and 200 then raise exception'Invalid runtime batch';end if;
 for r in select value from jsonb_array_elements(p_records)loop
  if jsonb_typeof(r)is distinct from'object'or not r?'runtime'then raise exception'Explicit runtime decision required';end if;
  select*into q from dm_private.bank_questions where active and external_key=r->>'externalKey'and content_sha256=r->>'contentSha256'for update;
  if not found then raise exception'Runtime record does not match active canonical content';end if;
  v:=nullif(r->'runtime','null'::jsonb);drawing:=q.question_type='DESCRIPTIVE';
  if v is not null then
   if jsonb_typeof(v)is distinct from'object'or q.exam not in('uceed','ceed')or q.question_type not in('NAT','MCQ','MSQ','DESCRIPTIVE')or q.payload->'holds'is distinct from'[]'::jsonb or v->>'kind'is distinct from(case when drawing then'drawing'else lower(q.question_type)end)or v->>'prompt'is distinct from q.payload->>'prompt'or v->'key'->>'sourceExternalKey'is distinct from q.external_key or v->'key'->>'kind'is distinct from v->>'kind'then raise exception'Invalid canonical runtime question';end if;
   if v->'context'->>'version'is distinct from'iitb-2027-v1'or v->'context'->>'cycle'is distinct from'2027'or v->'context'->>'exam'is distinct from q.exam then raise exception'Verified scoring context required';end if;
   if drawing then
    correct:=case when q.exam='uceed'then 50 else 20 end;wrong:=0;
    if v->'context'->>'part'is distinct from'B'or(v->'context'->>'durationSeconds')::integer<>(case when q.exam='uceed'then 3600 else 7200 end)or v->'marking'->>'correct'is null or(v->'marking'->>'correct')::numeric<>correct or(v->'marking'->>'wrong')::numeric<>0 or coalesce((v->'marking'->>'humanReview')::boolean,false)is not true or(v->>'points')::numeric<>correct or(v->>'negativePoints')::numeric<>0 or v->'options'is distinct from'[]'::jsonb or v->'key'is distinct from jsonb_build_object('kind','drawing','sourceExternalKey',q.external_key)then raise exception'Part B runtime must require verified human review';end if;
   else
    correct:=case when q.question_type='MCQ'then 3 else 4 end;wrong:=case when q.question_type='NAT'then 0 when q.question_type='MSQ'then-1 when q.exam='uceed'then-0.71 else-0.5 end;
    if v->'marking'->>'correct'is null or(v->'marking'->>'correct')::numeric<>correct or v->'marking'->>'wrong'is null or(v->'marking'->>'wrong')::numeric<>wrong or(v->>'points')::numeric is distinct from correct or(v->>'negativePoints')::numeric is distinct from abs(wrong)or coalesce((v->'marking'->>'partial')::boolean,false)<>(q.question_type='MSQ')then raise exception'Runtime marking does not match verified context';end if;
    if(q.question_type='NAT'and(jsonb_array_length(v->'options')<>0 or jsonb_typeof(v->'key'->'accepted')is distinct from'array'or jsonb_array_length(v->'key'->'accepted')=0))or(q.question_type in('MCQ','MSQ')and(jsonb_array_length(v->'options')<>4 or jsonb_typeof(v->'key'->'correct')is distinct from'array'or jsonb_array_length(v->'key'->'correct')=0))then raise exception'Incomplete runtime answer/options';end if;
    if q.question_type='NAT'then for a in select value from jsonb_array_elements(v->'key'->'accepted')loop if jsonb_typeof(a)is distinct from'object'or(a?'exact')=(a?'range')then raise exception'Invalid numeric answer';end if;if a?'exact'then if a->>'exact'is null or char_length(a->>'exact')>200 or a->>'exact'!~'^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$'then raise exception'Invalid exact numeric answer';end if;else if jsonb_typeof(a->'range')is distinct from'array'or jsonb_array_length(a->'range')<>2 or a->'range'->>0!~'^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$'or a->'range'->>1!~'^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$'or(a->'range'->>0)::numeric>(a->'range'->>1)::numeric then raise exception'Invalid numeric answer range';end if;end if;end loop;end if;
    if q.question_type in('MCQ','MSQ')then if v->'options'is distinct from(select jsonb_agg(jsonb_build_object('id',option->>'key','label',coalesce(nullif(btrim(option->>'text'),''),option->>'key')))from jsonb_array_elements(q.payload->'options')option)or(q.question_type='MCQ'and jsonb_array_length(v->'key'->'correct')<>1)or exists(select 1 from jsonb_array_elements_text(v->'key'->'correct')chosen where not exists(select 1 from jsonb_array_elements(v->'options')option where option->>'id'=chosen))or(select count(distinct chosen)from jsonb_array_elements_text(v->'key'->'correct')chosen)<>jsonb_array_length(v->'key'->'correct')then raise exception'Runtime options or key do not match canonical identifiers';end if;end if;
   end if;
   if jsonb_typeof(v->'options')is distinct from'array'or jsonb_typeof(v->'key')is distinct from'object'or jsonb_typeof(v->'media')is distinct from'array'or jsonb_typeof(q.payload->'assets')is distinct from'array'then raise exception'Invalid runtime structure';end if;
   if jsonb_array_length(v->'media')<>jsonb_array_length(q.payload->'assets')or(drawing and jsonb_array_length(v->'media')=0)or(coalesce((q.payload->>'visualDependency')::boolean,false)and jsonb_array_length(v->'media')=0)then raise exception'Canonical figures must be resolved';end if;
   for a in select value from jsonb_array_elements(q.payload->'assets')loop if not exists(select 1 from dm_private.bank_media_assets b where b.sha256=a->>'sha256'and b.width=(a->>'width')::integer and b.height=(a->>'height')::integer and exists(select 1 from jsonb_array_elements(v->'media')image where image->>'path'=b.storage_path and image->>'sha256'=b.sha256 and(image->>'width')::integer=b.width and(image->>'height')::integer=b.height))then raise exception'Runtime figure is not verified canonical media';end if;end loop;
   for m in select value from jsonb_array_elements(v->'media')loop if not exists(select 1 from jsonb_array_elements(q.payload->'assets')asset where asset->>'sha256'=m->>'sha256')then raise exception'Unreferenced runtime figure';end if;end loop;
  end if;
  update dm_private.bank_questions set runtime_payload=v,objective_ready=(v is not null and not drawing)where external_key=q.external_key;n:=n+1;
 end loop;return n;
end$$;

create or replace function public.topic_catalog()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,dm_private as $$begin if auth.uid()is null then raise exception'Sign in required';end if;return(select coalesce(jsonb_agg(jsonb_build_object('topic',topic,'exam',exam,'questions',questions)order by questions desc,topic,exam),'[]')from(select topic,exam,count(*)questions from dm_private.bank_questions where active and owner_approved and rights_confirmed and runtime_payload is not null and runtime_payload->>'kind'<>'drawing'group by topic,exam)c);end$$;

create or replace function public.start_topic_practice(p_topic text,p_exam text,p_count integer,p_duration_seconds integer)returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$
declare v_mode text;v_paper uuid;v_attempt uuid;v_seed uuid:=gen_random_uuid();v_question record;v_ordinal integer:=0;v_question_id uuid;
begin if auth.uid()is null then raise exception'Sign in required';end if;if p_exam not in('uceed','nid','nift','ceed')or p_count not in(10,20,30)or p_duration_seconds not in(900,1800,2700)then raise exception'Invalid practice configuration';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,1));select environment_mode into v_mode from public.launch_settings where singleton;if not exists(select 1 from dm_private.passes where user_id=auth.uid()and mode=v_mode and expires_at>now())then raise exception'An active pass is required';end if;if not exists(select 1 from public.profiles where user_id=auth.uid()and onboarding_completed_at is not null)then raise exception'Complete your verified profile first';end if;if(select count(*)from dm_private.attempts where user_id=auth.uid()and status='active'and deadline>now())>=3 then raise exception'Finish an active attempt before starting another';end if;if(select count(*)from dm_private.bank_questions where active and owner_approved and rights_confirmed and runtime_payload is not null and runtime_payload->>'kind'<>'drawing'and topic=p_topic and exam=p_exam)<p_count then raise exception'Not enough reviewed questions for this practice';end if;insert into dm_private.papers(title,exam,duration_seconds,published,reviewed,rights_confirmed,owner_user_id,source_kind)values(initcap(replace(p_topic,'-',' '))||' practice',p_exam,p_duration_seconds,false,true,true,auth.uid(),'topic')returning id into v_paper;for v_question in select*from dm_private.bank_questions where active and owner_approved and rights_confirmed and runtime_payload is not null and runtime_payload->>'kind'<>'drawing'and topic=p_topic and exam=p_exam order by md5(external_key||v_seed::text)limit p_count loop v_ordinal:=v_ordinal+1;insert into dm_private.questions(paper_id,ordinal,prompt,options,kind,marking,media,points,negative_points,topic,reviewed)values(v_paper,v_ordinal,v_question.runtime_payload->>'prompt',v_question.runtime_payload->'options',v_question.runtime_payload->>'kind',v_question.runtime_payload->'marking',v_question.runtime_payload->'media',(v_question.runtime_payload->>'points')::numeric,(v_question.runtime_payload->>'negativePoints')::numeric,v_question.topic,true)returning id into v_question_id;insert into dm_private.answer_keys(question_id,key,explanation)values(v_question_id,v_question.runtime_payload->'key',v_question.runtime_payload->>'explanation');end loop;insert into dm_private.attempts(user_id,paper_id,deadline)values(auth.uid(),v_paper,now()+make_interval(secs=>p_duration_seconds))returning id into v_attempt;insert into dm_private.attempt_items(attempt_id,question_id,ordinal,prompt,options,points,negative_points,topic,kind,marking,media,key,explanation)select v_attempt,q.id,q.ordinal,q.prompt,q.options,q.points,q.negative_points,q.topic,q.kind,q.marking,q.media,k.key,k.explanation from dm_private.questions q join dm_private.answer_keys k on k.question_id=q.id where q.paper_id=v_paper;return v_attempt;end$$;

revoke all on function public.upsert_question_bank_runtime_batch(jsonb)from public,anon,authenticated;
grant execute on function public.upsert_question_bank_runtime_batch(jsonb)to service_role;
